/* Country-linked family resources; allowance rates and contracts are explicit game rules. */
(function(root){
'use strict';
const month=()=>S.age*12+Math.floor((S.t||0)*12+1e-7),usd=n=>LifelineEconomy.toUSD(n);
function state(){return S.lifelineFamilyFinance||(S.lifelineFamilyFinance={lastMonth:month(),paid:0,supportYear:S.age,supportSpent:0,contract:null,blocked:false,brokenAt:null});}
function familyIncome(){const country=parFar()&&B()?B():C(),q=Math.max(1,Math.min(5,S.q||3)),percentile=S.flags.rich?.99:(q-.5)/5;return incomeAt(country,percentile)*(S.flags.rich===2?2:1);}
function available(){const f=state(),b=LifelineLifeActions.familyBonds();return !f.blocked&&famCanHelp()&&Math.max(b.bonds.mom||0,b.bonds.dad||0)>=30;}
function allowance(){const q=Math.max(1,Math.min(5,S.q||3));return S.age>=6&&S.age<18&&available()?familyIncome()*[.0005,.003,.007,.012,.02][q-1]*(S.age<12?.5:1)/12:0;}
function observe(){const f=state(),end=month();for(let m=f.lastMonth+1;m<=end;m++){
 const c=f.contract;if(c&&c.status==='active'){c.months++;if((c.requirement==='learning'?['study','learn','mind','career']:['help','family']).includes(S.focus))c.completed++;if(m>=c.due){if(c.completed>=c.required){c.status='kept';log('Вы выполнили договорённость с родителями. Они готовы поддерживать вас и дальше.','warm');}else {c.status='broken';f.blocked=true;f.brokenAt=S.age;const b=LifelineLifeActions.familyBonds();b.bonds.mom=Math.max(0,b.bonds.mom-12);b.bonds.dad=Math.max(0,b.bonds.dad-12);eff({so:-4});log('Условие помощи родителей не выполнено. Отношения стали напряжённее, и финансовая поддержка приостановлена.','bad');}}}
 if(m>=72&&m<216){const amount=allowance();if(amount>0){S.money+=amount;f.paid+=amount;book('Карманные деньги от семьи',amount);if(m===72||m%12===0)log('Семья даёт вам карманные деньги: '+usdStr(amount)+' в месяц.','note');}}
 }f.lastMonth=end;if(f.supportYear!==S.age){f.supportYear=S.age;f.supportSpent=0;}}
function supportOptions(){if(S.age<6||S.age>25||!(S.q>=5||S.flags.rich))return [];let items=[];try{items=shopItems().flatMap(item=>item.opts?item.opts.map(o=>({...o,n:item.n+' — '+o.n})):item);}catch{}const f=state(),limit=familyIncome()*(S.flags.rich?.4:.12)-f.supportSpent;
 return items.filter(i=>/^(?:own_phone|own_cell|own_pc|ged|nightuni|openuni|course|book|gear)/.test(i.id)&&i.price>0).map(i=>({id:i.id,name:text(i.n),cost:usd(i.price),disabled:!available()||!!(f.contract&&f.contract.status==='active')||i.price>limit,reason:!available()?'Финансовая помощь семьи сейчас приостановлена':f.contract?.status==='active'?'Сначала выполните текущую договорённость':i.price>limit?'Эта покупка превышает доступную помощь семьи на год':'',condition:'Родители оплатят покупку. В следующие 12 месяцев нужно уделять обучению приоритет не менее 6 месяцев. Если не выполнить — отношения ухудшатся, помощь прекратится.'}));}
function summary(){const f=state(),monthly=allowance(),b=LifelineLifeActions.familyBonds();return {monthly:usd(monthly),paid:usd(f.paid),familyIncome:usd(familyIncome()),country:text((parFar()&&B()?B():C()).ko),blocked:f.blocked,reason:S.age<6?'Вы ещё слишком малы для собственных карманных денег':S.age>=18?'Регулярные карманные деньги — до 18 лет':!available()?'Семья сейчас не оказывает финансовую помощь':'',contract:f.contract,options:supportOptions(),canDiscuss:f.blocked&&S.age>f.brokenAt&&Math.max(b.bonds.mom,b.bonds.dad)>=40};}
function perform(payload){if(S.phase!=='life'||S.pending||LifelineMoments.pending())throw Error('Сначала завершите текущий выбор');const f=state();if(payload.mode==='discuss'){if(!summary().canDiscuss)throw Error('Нужно время и восстановление отношений с родителями');f.blocked=false;f.contract=null;log('Вы обсудили прошлую договорённость с родителями. Они согласились дать вам ещё одну возможность.','note');return;}const option=supportOptions().find(i=>i.id===payload.item);if(!option||option.disabled)throw Error(option?.reason||'Эту покупку семья сейчас оплатить не может');const amount=LifelineEconomy.fromUSD(option.cost);S.money+=amount;const item=shopItems().flatMap(i=>i.opts||[i]).find(i=>i.id===payload.item&&i.avail);if(!item)throw Error('Кроме стоимости, не выполнены условия этой покупки');book('Родители оплатили покупку',amount);const note=buyShop(payload.item);if(!note)throw Error('Не удалось оформить покупку');f.supportSpent+=amount;f.contract={status:'active',item:option.name,amount:option.cost,requirement:'learning',start:month(),due:month()+12,required:6,completed:0,months:0};log(text(note)+' Вы договорились уделять обучению не менее 6 из следующих 12 месяцев.','big');}
function install(){const original=homeHelp;homeHelp=function(...args){return state().blocked?0:original.apply(this,args);};}
root.LifelineFamilyFinance={state,observe,summary,perform,install};
})(self);
